-- composition of rule kernels disjunctive_join_rewriter x redundant_order_keys (duckdb), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 ORDER BY 3, 3) AS ka UNION ALL SELECT 2 AS k FROM (FROM (VALUES (1, 2)) a(x, y) JOIN (VALUES (1, 2)) c(x, y) ON a.x = c.x OR a.y = c.y) AS kb) AS u;
-- pgfuzz:check kernel:union SELECT (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 ORDER BY 3, 3) AS ka) + (SELECT count(*) FROM (FROM (VALUES (1, 2)) a(x, y) JOIN (VALUES (1, 2)) c(x, y) ON a.x = c.x OR a.y = c.y) AS kb)
